// งานถูกอ่านจากคิวบนดิสก์ แอปอาจถูกปิดแล้วเปิดใหม่ระหว่างลองส่ง
Future<void> submit(ScanJob job) async {
  for (var attempt = 0; attempt < 3; attempt++) {
    try {
      await api.post("/scan", body: {
        "requestId": const Uuid().v4(),   // สร้างใหม่ทุกครั้งที่ลอง และไม่ได้เก็บลงคิว
        "boxNo": job.boxNo,
        "qty": job.qty,
      });
      return;
    } on SocketException {
      await Future.delayed(Duration(seconds: 2 * (attempt + 1)));
    }
  }
}
